package ro.whistlab.core.learning.evaluation;

import ro.whistlab.core.testing.match.OfflineMatchHarness;
import ro.whistlab.core.learning.tournament.RoundSevenTournamentTest;
import ro.whistlab.core.testing.RoundFourGameOracle;
import static org.junit.Assert.*;import com.fasterxml.jackson.databind.*;import java.nio.file.*;import java.time.Instant;import java.util.*;import org.junit.Test;import org.junit.runner.RunWith;import org.junit.runners.Parameterized;
/** One actual complete offline game per declared league/seed/seating; no UI or privileged player observations. */
@RunWith(Parameterized.class)
public class StrategyArenaTest {
 private static final ObjectMapper JSON=new ObjectMapper();
 @Parameterized.Parameters(name="league={0},seed={1},seating={2}")public static Collection<Object[]> cases()throws Exception{
  byte[] bytes=Files.readAllBytes(Path.of(required("whist.arena.protocol")));var p=JSON.readTree(bytes);assertEquals(1,p.path("schemaVersion").asInt());assertEquals("ROMANIAN4_SERIES10",p.path("profile").asText());assertEquals("development",p.path("partition").asText());int first=p.path("firstSeed").asInt(),seeds=p.path("seeds").asInt();assertTrue(first>=0&&seeds>0&&seeds<=1000);var cases=new ArrayList<Object[]>();var arrangements=new HashSet<String>();
  for(var arrangement:p.path("arrangements")){assertEquals(4,arrangement.size());var indexes=new HashSet<Integer>();for(var i:arrangement)assertTrue(indexes.add(i.asInt())&&i.asInt()>=0&&i.asInt()<4);assertTrue("Duplicate arrangement",arrangements.add(arrangement.toString()));}
  for(var league:p.path("leagues")){assertTrue(league.path("id").asText().matches("[a-z0-9-]+"));assertEquals(4,league.path("profiles").size());for(int seed=first;seed<first+seeds;seed++)for(int seating=0;seating<p.path("arrangements").size();seating++){var ids=new ArrayList<String>();for(var index:p.path("arrangements").get(seating))ids.add(league.path("profiles").get(index.asInt()).asText());assertEquals(4,new HashSet<>(ids).size());cases.add(new Object[]{league.path("id").asText(),seed,seating,List.copyOf(ids),hash(bytes)});}}
  return cases;
 }
 private final String league,protocolHash;private final int seed,seating;private final List<String> profiles;
 public StrategyArenaTest(String league,int seed,int seating,List<String> profiles,String protocolHash){this.league=league;this.seed=seed;this.seating=seating;this.profiles=profiles;this.protocolHash=protocolHash;}
 @Test public void completeHeterogeneousGameMatchesIndependentRulesAndScoring()throws Exception{
  Path protocol=Path.of(required("whist.arena.protocol"));byte[] protocolBytes=Files.readAllBytes(protocol);assertEquals("Protocol changed after declaring cases",protocolHash,hash(protocolBytes));var p=JSON.readTree(protocolBytes);var profileMap=new HashMap<String,JsonNode>();for(var profile:p.path("profiles"))assertNull("Duplicate profile",profileMap.put(profile.path("id").asText(),profile));
  Path out=Path.of(required("whist.arena.output")),corpus=Path.of(required("whist.arena.corpus"));Files.createDirectories(out.resolve("invocations"));Files.createDirectories(out.resolve("partial-games"));
  var hashes=new TreeMap<>(RoundSevenTournamentTest.policyHashes());Path project=Path.of(System.getProperty("user.dir")).getParent();for(String file:List.of("game-core/src/test/java/ro/whistlab/coach/strategy/SafetyGreedyPlayer.java","game-core/src/test/java/ro/whistlab/coach/strategy/SafetyCoversPlayer.java","game-core/src/test/java/ro/whistlab/core/learning/evaluation/StrategyArenaTest.java"))hashes.put(file,hash(Files.readAllBytes(project.resolve(file))));
  Path sourceFile=out.resolve("source-hashes.json");if(Files.exists(sourceFile))assertEquals(JSON.valueToTree(hashes),JSON.readTree(Files.readAllBytes(sourceFile)));else RoundSevenTournamentTest.write(sourceFile,hashes);
  Path savedProtocol=out.resolve("protocol.json");if(Files.exists(savedProtocol))assertEquals(protocolHash,hash(Files.readAllBytes(savedProtocol)));else Files.copy(protocol,savedProtocol);
  String id="arena-"+p.path("id").asText()+"-"+league+"-seed"+seed+"-seating"+seating;Path receiptFile=out.resolve("invocations/"+id+".json");assertFalse("Closed invocation IDs are immutable",Files.exists(receiptFile));var checkpoints=new ArrayList<Object>();var results=new ArrayList<Map<String,Object>>();var receipt=new LinkedHashMap<String,Object>();long begin=System.nanoTime();receipt.put("schemaVersion",1);receipt.put("runId",p.path("id").asText());receipt.put("invocationId",id);receipt.put("className",getClass().getName());receipt.put("methodName","completeHeterogeneousGameMatchesIndependentRulesAndScoring");receipt.put("parameters",Map.of("collection",seed==p.path("firstSeed").asInt()&&seating==0?"documentation":"learning","league",league,"seed",Integer.toString(seed),"seating",seating));receipt.put("startedAt",Instant.now().toString());receipt.put("status","RUNNING");receipt.put("sourceHashes",hashes);receipt.put("protocolSha256",protocolHash);receipt.put("checkpoints",checkpoints);receipt.put("results",results);RoundSevenTournamentTest.write(receiptFile,receipt);
  try{
   var controllers=new ArrayList<OfflineMatchHarness.Policy>();var bySeat=new ArrayList<Map<String,Object>>();for(int seat=0;seat<4;seat++){var profile=Objects.requireNonNull(profileMap.get(profiles.get(seat)),"Unknown strategy");var policy=OfflineMatchHarness.Policy.valueOf(profile.path("controller").asText());controllers.add(policy);bySeat.add(OfflineMatchHarness.map("seat",seat,"profile",profiles.get(seat),"controller",policy.name(),"objective",profile.path("objective").asText(),"covers",profile.path("covers").asBoolean(),"bidSamples",profile.path("bidSamples").isNumber()?profile.path("bidSamples").asInt():profile.path("bidSamples").asText(),"cardSamples",profile.path("cardSamples").asInt()));}
   checkpoints.add(Map.of("owner",id+"/profiles","title","Four declared strategies and balanced seating","context",Map.of("league",league,"seed",seed,"seating",seating,"profilesBySeat",bySeat,"scope",p.path("design").asText(),"interpretation",p.path("leagues").findValuesAsText("interpretation")),"comparisons",List.of(Map.of("name","Four distinct strategy profiles","expected",4,"actual",new HashSet<>(profiles).size(),"passed",new HashSet<>(profiles).size()==4))));
   var game=OfflineMatchHarness.playWithControllers(id,seed,0,controllers,g->{try{RoundSevenTournamentTest.write(out.resolve("partial-games/"+id+".json"),g);}catch(Exception error){throw new IllegalStateException("Cannot retain last safe hand",error);}});
   var source=(Map<String,Object>)game.get("source");source.remove("heroSeat");source.put("kind","offline-arena");source.put("policyBySeat",bySeat);source.put("sourceHashes",hashes);source.put("protocolSha256",protocolHash);source.put("invocationId",id);var players=(List<Map<String,Object>>)game.get("players");for(int seat=0;seat<4;seat++)players.get(seat).put("controller",profiles.get(seat));
   Path gameFile=corpus.resolve("games/development/"+id+".json");Files.createDirectories(gameFile.getParent());assertFalse("Game files are immutable",Files.exists(gameFile));RoundSevenTournamentTest.write(gameFile,game);
   var audit=RoundFourGameOracle.audit(game);checkpoints.addAll(audit);assertTrue("Independent rules/scoring comparison failed",audit.stream().flatMap(c->c.comparisons().stream()).allMatch(RoundFourGameOracle.Comparison::passed));
   var totals=(List<Integer>)game.get("finalScores");int best=totals.stream().mapToInt(Integer::intValue).max().orElseThrow();long ties=totals.stream().filter(x->x==best).count();
   for(int seat=0;seat<4;seat++){var sizes=new TreeMap<String,Map<String,Integer>>();int exact=0;for(var hand:(List<Map<String,Object>>)game.get("hands")){var score=((List<Map<String,Object>>)hand.get("scores")).get(seat);var metrics=sizes.computeIfAbsent(hand.get("size").toString(),k->new TreeMap<>(Map.of("hands",0,"exact",0,"points",0,"absoluteBidError",0)));boolean made=score.get("bid").equals(score.get("won"));if(made)exact++;metrics.merge("hands",1,Integer::sum);metrics.merge("exact",made?1:0,Integer::sum);metrics.merge("points",((Number)score.get("base")).intValue()+((Number)score.get("series")).intValue(),Integer::sum);metrics.merge("absoluteBidError",Math.abs(((Number)score.get("won")).intValue()-((Number)score.get("bid")).intValue()),Integer::sum);}
    results.add(OfflineMatchHarness.map("profile",profiles.get(seat),"seat",seat,"gameId",id,"points",totals.get(seat),"winShare",totals.get(seat)==best?1.0/ties:0.0,"exact",exact,"byHandSize",sizes));}
   var uniqueOwners=new HashSet<String>();for(var checkpoint:JSON.valueToTree(checkpoints))assertTrue("Repeated evidence owner",uniqueOwners.add(checkpoint.path("owner").asText()));
   receipt.put("status","PASS");
  }catch(AssertionError error){receipt.put("status","FAIL");receipt.put("failure",error.toString());throw error;}catch(Exception error){receipt.put("status","ERROR");receipt.put("failure",error.toString());throw error;}finally{receipt.put("endedAt",Instant.now().toString());receipt.put("durationNanos",System.nanoTime()-begin);RoundSevenTournamentTest.write(receiptFile,receipt);}
 }
 private static String required(String key){String value=System.getProperty(key,"");assertFalse("Missing "+key,value.isBlank());return value;}
 private static String hash(byte[] bytes)throws Exception{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));}
}
